#include <iostream>
#include <string>

/* 鱼摊的价目台：档位、单价、算账都归它管。
   柜台名规矩：全小写加下划线 —— fish_market 就是样板 */
namespace fish_market {

/* 档位清单：枚举值也是「常量」，k 开头、后面词头大写 */
enum class MemberClass {
    kGuest = 0,
    kRegular = 1,
    kVip = 2
};

/* 每斤单价（收多少条小鱼干）：常量规矩 —— k 开头 + 词头大写 */
constexpr int kGuestPrice = 1;
constexpr int kRegularPrice = 3;
constexpr int kVipPrice = 5;

int PriceOf(MemberClass member) {
    if (member == MemberClass::kGuest) {
        return kGuestPrice;
    }
    if (member == MemberClass::kRegular) {
        return kRegularPrice;
    }
    return kVipPrice;
}

std::string NameOf(MemberClass member) {
    if (member == MemberClass::kGuest) {
        return "散客";
    }
    if (member == MemberClass::kRegular) {
        return "常客";
    }
    return "贵宾";
}

}  // namespace fish_market

int main() {
    int tier = 0;
    std::cin >> tier;

    fish_market::MemberClass member = fish_market::MemberClass::kGuest;
    if (tier == 1) {
        member = fish_market::MemberClass::kRegular;
    } else if (tier == 2) {
        member = fish_market::MemberClass::kVip;
    }

    int n = 0;
    std::cin >> n;
    int total_weight = 0;
    for (int i = 0; i < n; i++) {
        int w = 0;
        std::cin >> w;
        total_weight = total_weight + w;
    }

    int bill = total_weight * fish_market::PriceOf(member);
    std::cout << "档位：" << fish_market::NameOf(member) << std::endl;
    std::cout << "应收 " << bill << " 条喵" << std::endl;
    return 0;
}

explanationTemplate:
**一、价目台的命名规矩逐条过。**

**柜台名**：`namespace fish_market` —— 全小写、词间下划线。招牌一眼能认：这是本摊的价目台，跟普通名字分得开。

**档位清单**：

```text
enum class MemberClass {
    kGuest = 0,
    kRegular = 1,
    kVip = 2
};
```

枚举里那三个值**本质是常量**，所以按常量的手势起名：`k` 开头 + 后面每个词头大写。最容易踩的坑是写成宏那样的大写（`GUEST`、`REGULAR`）—— 那会让读者以为它们是 `#define` 小字条。Google 的规矩说得很直白：**枚举值用常量的起名法，别用宏的起名法**。

**单价常量**：

```text
constexpr int kGuestPrice = 1;
constexpr int kRegularPrice = 3;
constexpr int kVipPrice = 5;
```

`k` 开头是流传很久的常量暗号：早年流行的命名传统里，k 专用来指「一锤定音、不再变的数」。Google 把它收编成正式规矩：**常量名 k 开头 + 词头大写**。一眼看见 `k` 打头，不用翻定义就知道这是个一辈子不变的数。

**二、两招的写法。**

```text
int PriceOf(MemberClass member) {
    if (member == MemberClass::kGuest) {
        return kGuestPrice;
    }
    if (member == MemberClass::kRegular) {
        return kRegularPrice;
    }
    return kVipPrice;
}
```

三处细节多念两遍喵：比较档位要写全名 `MemberClass::kGuest` —— `enum class` 的值被锁在清单里，不会像老式枚举那样到处乱飘；三个常量不是摆设，正是要在这里被叼回去，**价只在价目台上写一处**；招式名 `PriceOf` 首字母大写，跟口袋名、常量名一眼分家。

```text
std::string NameOf(MemberClass member) {
    if (member == MemberClass::kGuest) {
        return "散客";
    }
    if (member == MemberClass::kRegular) {
        return "常客";
    }
    return "贵宾";
}
```

**三、为什么值要起名。** 要是把 1、3、5 直接钉死在算账的算式里，改价那天就得满程序翻；起成 `kGuestPrice` 之后，价目台成了唯一改动点，算式里读到的也是「贵宾价」这块牌子，不是裸的 5。

一句话收好：**柜台小写下划线、档位与单价都 k 开头、招式大驼峰；值起好名，改价只改一处喵。**
